package ru.truetv.launcher;
import android.content.*;
import android.content.pm.*;
import android.os.*;
import android.provider.Settings;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.spec.*;
import java.security.interfaces.*;
import java.util.*;

/** Privileged paths exist only for explicitly confirmed expert operations. */
public final class ExpertBackend implements AutoCloseable {
 private final Context context;private final boolean root;private final AdbWire adb;
 public ExpertBackend(Context c,boolean root,String endpoint)throws Exception {context=c.getApplicationContext();this.root=root;adb=root?null:new AdbWire(endpoint,keys(context));try{if(root){ShellReply id=shell("id -u");if(id.code!=0||!id.text.trim().equals("0"))throw new IOException("Root not granted");}else proveSameDevice();}catch(Exception e){close();throw e;}}
 public static int user(){return android.os.Process.myUid()/100000;}
 public ShellReply shell(String cmd)throws Exception {return root?RootCommand.run(cmd,45000):adb.shell(cmd);}
 public boolean isRoot(){return root;}
 public boolean hasRootShell()throws Exception {if(root)return true;ShellReply id=shell("id -u");return id.code==0&&id.text.trim().equals("0");}
 public void prepareOverride(String pkg)throws Exception {SystemCommands.validate(pkg,user());if(pkg.equals(context.getPackageName())||pkg.equals("android"))throw new IOException("Нельзя удалить сам работающий инструмент или базовый пакет android");ApplicationInfo info=context.getPackageManager().getApplicationInfo(pkg,PackageManager.MATCH_UNINSTALLED_PACKAGES|PackageManager.MATCH_DISABLED_COMPONENTS);if((info.flags&(ApplicationInfo.FLAG_SYSTEM|ApplicationInfo.FLAG_UPDATED_SYSTEM_APP))==0)throw new IOException("Это не системное приложение");ResolveInfo home=context.getPackageManager().resolveActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME),PackageManager.MATCH_DEFAULT_ONLY);if(home!=null&&home.activityInfo.packageName.equals(pkg)){HomeDefaults.assign(this::shell,user(),Build.VERSION.SDK_INT);}}
 public void performOverride(String pkg,SystemCommands.Operation op)throws Exception {
  if(op==SystemCommands.Operation.DISABLE){SystemCommands.validate(pkg,user());if(pkg.equals(context.getPackageName())||pkg.equals("android"))throw new IOException("Нельзя отключить этот лаунчер или android");PackageManager pm=context.getPackageManager();ApplicationInfo app=pm.getApplicationInfo(pkg,PackageManager.MATCH_DISABLED_COMPONENTS);if((app.flags&(ApplicationInfo.FLAG_SYSTEM|ApplicationInfo.FLAG_UPDATED_SYSTEM_APP))==0)throw new IOException("Это не системное приложение");ResolveInfo home=pm.resolveActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME),PackageManager.MATCH_DEFAULT_ONLY);if(home!=null&&home.activityInfo!=null&&pkg.equals(home.activityInfo.packageName)){HomeDefaults.freezeCurrent(this::shell,pkg,user(),Build.VERSION.SDK_INT,pm.getApplicationEnabledSetting(pkg));return;}}
  prepareOverride(pkg);ShellReply changed=shell(SystemCommands.mutation(op,pkg,user()));ShellReply state=shell(SystemCommands.query(op,pkg,user()));if(changed.code!=0||state.code!=0||!SystemCommands.confirmed(op,pkg,state.text))throw new IOException("Изменение не подтверждено: "+changed.text);}
 public String removeEverywhere(String pkg)throws Exception {prepareOverride(pkg);List<Integer> users=PackagePolicy.users(shell("pm list users").text);shell("pm uninstall "+pkg);for(int u:users){ShellReply state=shell(SystemCommands.query(SystemCommands.Operation.REMOVE,pkg,u));if(state.code!=0)throw new IOException("Не прочитан профиль "+u);if(!SystemCommands.confirmed(SystemCommands.Operation.REMOVE,pkg,state.text)){ShellReply changed=shell(PackagePolicy.removeProfile(pkg,u));ShellReply after=shell(SystemCommands.query(SystemCommands.Operation.REMOVE,pkg,u));if(changed.code!=0||after.code!=0||!SystemCommands.confirmed(SystemCommands.Operation.REMOVE,pkg,after.text))throw new IOException("Удаление не подтверждено для профиля "+u+": "+changed.text);}}return Ui.word(context,"Приложение удалено из всех профилей Android. Для удаления заводского APK из прошивки выберите «Физически удалить заводской APK». Нужны root-права и доступный на запись раздел.","The app was removed from all Android profiles. To erase its factory APK from firmware, choose Physically delete factory APK. Root privileges and a writable partition are required.");}
 public void restoreEverywhere(String pkg)throws Exception {SystemCommands.validate(pkg,user());for(int u:PackagePolicy.users(shell("pm list users").text)){ShellReply changed=shell(SystemCommands.mutation(SystemCommands.Operation.RESTORE,pkg,u));ShellReply state=shell(SystemCommands.query(SystemCommands.Operation.RESTORE,pkg,u));if(changed.code!=0||state.code!=0||!SystemCommands.confirmed(SystemCommands.Operation.RESTORE,pkg,state.text))throw new IOException("Восстановление не подтверждено для профиля "+u);}}
 private static synchronized KeyPair keys(Context c)throws Exception {File file=new File(c.getFilesDir(),"expert-adb-private.pk8");if(file.exists())return AdbIdentity.restore(read(file,8192));KeyPairGenerator generator=KeyPairGenerator.getInstance("RSA");generator.initialize(2048);KeyPair pair=generator.generateKeyPair();try(FileOutputStream out=c.openFileOutput(file.getName(),Context.MODE_PRIVATE)){out.write(pair.getPrivate().getEncoded());out.getFD().sync();}return pair;}
 private static byte[] read(File file,int cap)throws IOException {try(InputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[1024];int n;while((n=in.read(buffer))>=0){if(out.size()+n>cap)throw new IOException("Key too large");out.write(buffer,0,n);}return out.toByteArray();}}
 private void proveSameDevice()throws Exception {File folder=context.getExternalFilesDir("expert");if(folder==null||!folder.exists()&&!folder.mkdirs())throw new IOException("Local storage unavailable for ADB target verification");File challenge=new File(folder,"target-"+UUID.randomUUID()+".txt");String expected=UUID.randomUUID().toString()+UUID.randomUUID();try{try(FileOutputStream out=new FileOutputStream(challenge)){out.write(expected.getBytes(StandardCharsets.UTF_8));out.getFD().sync();}ShellReply reply=shell("cat "+quote(challenge.getAbsolutePath()));if(reply.code!=0||!reply.text.trim().equals(expected))throw new IOException("ADB target is not this device or cannot verify local storage; operation blocked");}finally{challenge.delete();}}
 private static String quote(String s){return "'"+s.replace("'","'\\''")+"'";}
 public static String protectedReason(Context c,ApplicationInfo app){String pkg=app.packageName;if(pkg.equals(c.getPackageName())||pkg.equals("android")||(app.flags&ApplicationInfo.FLAG_PERSISTENT)!=0||Arrays.asList("com.android.systemui","com.android.providers.settings","com.android.settings","com.android.tv.settings","com.android.permissioncontroller","com.google.android.permissioncontroller","com.android.packageinstaller","com.google.android.packageinstaller","com.android.bluetooth").contains(pkg))return Ui.word(c,"Ключевой компонент системы","Core system component");try{ResolveInfo home=c.getPackageManager().resolveActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME),PackageManager.MATCH_DEFAULT_ONLY);if(home!=null&&home.activityInfo.packageName.equals(pkg))return Ui.word(c,"Текущий основной лаунчер. Сначала выберите другой.","Current default Home. Select another first.");String ime=Settings.Secure.getString(c.getContentResolver(),Settings.Secure.DEFAULT_INPUT_METHOD);if(ime!=null&&ime.startsWith(pkg+"/"))return Ui.word(c,"Текущая клавиатура","Current keyboard");}catch(RuntimeException ignored){}return null;}
 public static void validateTarget(Context c,String pkg)throws Exception {SystemCommands.validate(pkg,user());ApplicationInfo app=c.getPackageManager().getApplicationInfo(pkg,PackageManager.MATCH_UNINSTALLED_PACKAGES|PackageManager.MATCH_DISABLED_COMPONENTS);if((app.flags&(ApplicationInfo.FLAG_SYSTEM|ApplicationInfo.FLAG_UPDATED_SYSTEM_APP))==0)throw new IOException("Only system apps are allowed here");String reason=protectedReason(c,app);if(reason!=null)throw new IOException(reason);}
 public void perform(String pkg,SystemCommands.Operation operation)throws Exception {validateTarget(context,pkg);ShellReply changed=shell(SystemCommands.mutation(operation,pkg,user()));if(changed.code!=0)throw new IOException(changed.text.isEmpty()?"Package manager rejected operation":changed.text);ShellReply state=shell(SystemCommands.query(operation,pkg,user()));if(state.code!=0||!SystemCommands.confirmed(operation,pkg,state.text))throw new IOException("Operation result not confirmed. Refresh the list.");}
 public void close()throws IOException {if(adb!=null)adb.close();}
}
